func serializeMetadata(s smithy.ShapeSerializer, schema *smithy.Schema, v map[string]string) {
	if v == nil {
		return
	}
	s.WriteMap(schema)
	for k, vv := range v {
		s.WriteKey(schema.MapKey(), k)
		s.WriteString(schema.MapValue(), string(vv))
	}
	s.CloseMap()
}

